/* @component: .cards-more */
(function() {
  function initPortionLoader() {
    const containers = document.querySelectorAll('.cards-more');

    containers.forEach(container => {
      if (container.dataset.initialized) return;

      const btn = container.querySelector('.cards-more__btn');
      const list = container.querySelector('.cards-more__list');
      if (!btn || !list) return;

      const items = list.querySelectorAll('.card');
      const STEP = 5;
      let visibleCount = STEP;

      function update() {
        items.forEach((item, idx) => {
          if (idx < visibleCount) {
            item.style.display = 'block';
            setTimeout(() => { item.style.opacity = '1'; }, 10);
          } else {
            item.style.display = 'none';
            item.style.opacity = '0';
          }
        });

        if (visibleCount >= items.length) {
          btn.textContent = 'SHOW LESS';
          btn.classList.add('_full');
        } else {
          btn.textContent = 'LOAD MORE';
          btn.classList.remove('_full');
        }
      }

      btn.addEventListener('click', (e) => {
        e.preventDefault();
        if (btn.classList.contains('_full')) {
          visibleCount = STEP;
          container.scrollIntoView({ behavior: 'smooth' });
        } else {
          visibleCount += STEP;
        }
        update();
      });

      container.dataset.initialized = 'true';
      update();
    });
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', initPortionLoader);
  } else {
    initPortionLoader();
  }

  setTimeout(initPortionLoader, 300);
  setTimeout(initPortionLoader, 1000);
})();
